// csscolor.mjs — CSS color string parser (no dependencies)

export class ColorError extends Error {
  constructor(token, detail = '') {
    super(`Invalid color${detail ? ': ' + detail : ''} — bad token: ${JSON.stringify(token)}`);
    this.name = 'ColorError';
    this.token = token;
  }
}

const NAMED_COLORS = {
  red: [255, 0, 0],
  lime: [0, 255, 0],
  blue: [0, 0, 255],
  white: [255, 255, 255],
  black: [0, 0, 0],
  rebeccapurple: [102, 51, 153],
};

const HEX_DIGITS = '0123456789abcdef';

function expandHexPair(d) {
  return parseInt(d + d, 16);
}

function clampByte(v) {
  const n = Math.round(v);
  return Math.min(255, Math.max(0, n));
}

function clampAlpha(v) {
  return Math.min(1, Math.max(0, v));
}

// Standard HSL -> RGB conversion (per CSS Color Module).
function hslToRgb(h, s, l) {
  let hue = ((h % 360) + 360) % 360;
  const sat = Math.min(1, Math.max(0, s));
  const lig = Math.min(1, Math.max(0, l));

  const c = (1 - Math.abs(2 * lig - 1)) * sat;
  const hp = hue / 60;
  const x = c * (1 - Math.abs((hp % 2) - 1));

  let r1 = 0, g1 = 0, b1 = 0;
  if (hp < 1)      [r1, g1, b1] = [c, x, 0];
  else if (hp < 2) [r1, g1, b1] = [x, c, 0];
  else if (hp < 3) [r1, g1, b1] = [0, c, x];
  else if (hp < 4) [r1, g1, b1] = [0, x, c];
  else if (hp < 5) [r1, g1, b1] = [x, 0, c];
  else             [r1, g1, b1] = [c, 0, x];

  const m = lig - c / 2;
  return [
    Math.round((r1 + m) * 255),
    Math.round((g1 + m) * 255),
    Math.round((b1 + m) * 255),
  ];
}

function parseChannel(token) {
  const t = token.trim();
  if (t.endsWith('%')) {
    const num = Number(t.slice(0, -1));
    if (!Number.isFinite(num)) throw new ColorError(token, 'expected a number or percentage');
    return clampByte((num / 100) * 255);
  }
  const num = Number(t);
  if (!Number.isFinite(num)) throw new ColorError(token, 'expected a number or percentage');
  return clampByte(num);
}

function parseAlpha(token) {
  const t = token.trim();
  if (t.endsWith('%')) {
    const num = Number(t.slice(0, -1));
    if (!Number.isFinite(num)) throw new ColorError(token, 'expected an alpha value');
    return clampAlpha(num / 100);
  }
  const num = Number(t);
  if (!Number.isFinite(num)) throw new ColorError(token, 'expected an alpha value');
  return clampAlpha(num);
}

function parseFunctional(name, inner) {
  const isAlphaForm = name.toLowerCase() === 'rgba' || name.toLowerCase() === 'hsla';
  const args = inner.includes(',')
    ? inner.split(',')
    : inner.trim().split(/\s+/);

  const clean = args.map((a) => a.trim()).filter((a) => a !== '');
  if (inner.trim() === '') throw new ColorError(inner, `empty argument list`);

  if (name.toLowerCase().startsWith('rgb')) {
    const expected = isAlphaForm ? 4 : 3;
    if (clean.length !== expected && !(isAlphaForm && clean.length === 3)) {
      throw new ColorError(inner, `rgb() expects ${expected} arguments, got ${clean.length}`);
    }
    const r = parseChannel(clean[0]);
    const g = parseChannel(clean[1]);
    const b = parseChannel(clean[2]);
    const a = clean.length === 4 ? parseAlpha(clean[3]) : 1;
    return { r, g, b, a };
  }

  // hsl / hsla
  const expected = isAlphaForm ? 4 : 3;
  if (clean.length !== expected && !(isAlphaForm && clean.length === 3)) {
    throw new ColorError(inner, `hsl() expects ${expected} arguments, got ${clean.length}`);
  }

  // Hue: optional "deg" unit, plain number.
  const hueTok = clean[0];
  const hueMatch = /^(-?\d*\.?\d+)\s*(deg)?$/.exec(hueTok);
  if (!hueMatch) throw new ColorError(hueTok, 'expected a hue angle like "120" or "120deg"');
  const hue = Number(hueMatch[1]);

  const satTok = clean[1];
  if (!satTok.endsWith('%')) throw new ColorError(satTok, 'expected a saturation percentage like "100%"');
  const sat = Number(satTok.slice(0, -1));
  if (!Number.isFinite(sat)) throw new ColorError(satTok, 'expected a saturation percentage');

  const ligTok = clean[2];
  if (!ligTok.endsWith('%')) throw new ColorError(ligTok, 'expected a lightness percentage like "50%"');
  const lig = Number(ligTok.slice(0, -1));
  if (!Number.isFinite(lig)) throw new ColorError(ligTok, 'expected a lightness percentage');

  const [r, g, b] = hslToRgb(hue, sat / 100, lig / 100);
  const a = clean.length === 4 ? parseAlpha(clean[3]) : 1;
  return { r, g, b, a };
}

export function parseColor(input) {
  if (typeof input !== 'string') {
    throw new ColorError(String(input), 'color must be a string');
  }
  const str = input.trim();

  if (str === '') throw new ColorError('', 'empty color string');

  // Hex forms: #rgb, #rgba, #rrggbb, #rrggbbaa
  if (str.startsWith('#')) {
    const hex = str.slice(1).toLowerCase();
    if (![3, 4, 6, 8].includes(hex.length) || !/^[\da-f]+$/.test(hex)) {
      throw new ColorError(str, 'hex color must be #rgb, #rgba, #rrggbb or #rrggbbaa');
    }
    if (hex.length === 3 || hex.length === 4) {
      const chars = [...hex];
      const r = expandHexPair(chars[0]);
      const g = expandHexPair(chars[1]);
      const b = expandHexPair(chars[2]);
      const a = chars.length === 4 ? clampAlpha(parseInt(chars[3] + chars[3], 16) / 255) : 1;
      return { r, g, b, a };
    }
    const r = parseInt(hex.slice(0, 2), 16);
    const g = parseInt(hex.slice(2, 4), 16);
    const b = parseInt(hex.slice(4, 6), 16);
    const a = hex.length === 8 ? clampAlpha(parseInt(hex.slice(6, 8), 16) / 255) : 1;
    return { r, g, b, a };
  }

  // Named colors
  const lower = str.toLowerCase();
  if (Object.prototype.hasOwnProperty.call(NAMED_COLORS, lower)) {
    const [r, g, b] = NAMED_COLORS[lower];
    return { r, g, b, a: 1 };
  }

  // Functional notation: rgb(), rgba(), hsl(), hsla()
  const funcMatch = /^(rgba?|hsla?)\s*\((.*)\)$/.exec(str);
  if (funcMatch) {
    return parseFunctional(funcMatch[1], funcMatch[2]);
  }

  throw new ColorError(str, 'unrecognized color format');
}

