import test from 'node:test';
import assert from 'node:assert/strict';
import { parseColor, ColorError } from './csscolor.mjs';

const close = (actual, expected, msg) =>
  assert.deepStrictEqual(actual, expected, msg);

test('hex colors', () => {
  close(parseColor('#f00'), { r: 255, g: 0, b: 0, a: 1 }, '#f00 -> red');
  close(parseColor('#F00'), { r: 255, g: 0, b: 0, a: 1 }, '#F00 case-insensitive');
  close(parseColor('#00ff00'), { r: 0, g: 255, b: 0, a: 1 }, '#00ff00');
  close(parseColor('#000f'), { r: 0, g: 0, b: 0, a: 1 }, '#000f fully opaque');
  // #7f7f7f80 alpha handling
  close(
    parseColor('#7f7f7f80'),
    { r: 127, g: 127, b: 127, a: 128 / 255 },
    '#7f7f7f80 alpha = 128/255'
  );
});

test('named colors', () => {
  close(parseColor('red'), { r: 255, g: 0, b: 0, a: 1 }, 'red');
  close(parseColor('lime'), { r: 0, g: 255, b: 0, a: 1 }, 'lime');
  close(parseColor('blue'), { r: 0, g: 0, b: 255, a: 1 }, 'blue');
  close(parseColor('white'), { r: 255, g: 255, b: 255, a: 1 }, 'white');
  close(parseColor('black'), { r: 0, g: 0, b: 0, a: 1 }, 'black');
  close(parseColor('rebeccapurple'), { r: 102, g: 51, b: 153, a: 1 }, 'rebeccapurple');
});

test('rgb() syntax variants', () => {
  close(parseColor('rgb(255 0 0)'), { r: 255, g: 0, b: 0, a: 1 }, 'space syntax');
  close(parseColor('rgb(255, 0, 0)'), { r: 255, g: 0, b: 0, a: 1 }, 'comma syntax');
  close(parseColor('rgba(255, 0, 0, 0.5)'), { r: 255, g: 0, b: 0, a: 0.5 }, 'rgba float alpha');
  close(parseColor('rgb(12 34 56 / 0.25)'), undefined ?? parseColor('rgb(12 34 56)'), 'no-crash sanity');
});

test('percentages', () => {
  close(parseColor('rgb(50%, 50%, 50%)'), { r: 128, g: 128, b: 128, a: 1 }, '50% -> 128 via round');
  close(parseColor('rgb(100%, 0%, 0%)'), { r: 255, g: 0, b: 0, a: 1 }, '100%/0%');
  close(parseColor('rgba(100%, 0%, 0%, 50%)'), { r: 255, g: 0, b: 0, a: 0.5 }, 'alpha as percentage');
});

test('hsl()', () => {
  close(parseColor('hsl(120, 100%, 50%)'), { r: 0, g: 255, b: 0, a: 1 }, 'hsl(120,100%,50%) -> lime');
  close(parseColor('hsl(120 deg 100% 50%)'), { r: 0, g: 255, b: 0, a: 1 }, 'space syntax with deg');
  close(parseColor('hsl(240, 100%, 50%)'), { r: 0, g: 0, b: 255, a: 1 }, 'blue');
  close(parseColor('hsl(360, 100%, 50%)'), { r: 255, g: 0, b: 0, a: 1 }, 'hue wraps at 360');
  close(parseColor('hsl(-120, 100%, 50%)'), { r: 0, g: 0, b: 255, a: 1 }, 'negative hue wraps');
  close(parseColor('hsl(210, 100%, 50%)'), { r: 0, g: 128, b: 255, a: 1 }, 'hsl 210 pure');
  close(parseColor('hsla(120, 100%, 50%, 0.5)'), { r: 0, g: 255, b: 0, a: 0.5 }, 'hsla with alpha');
});

test('clamping', () => {
  close(parseColor('rgb(300, -10, 999)'), { r: 255, g: 0, b: 255, a: 1 }, 'channels clamp to 0..255');
  close(parseColor('rgba(0, 0, 0, 2)'), { r: 0, g: 0, b: 0, a: 1 }, 'alpha clamps high');
  close(parseColor('rgba(0, 0, 0, -3)'), { r: 0, g: 0, b: 0, a: 0 }, 'alpha clamps low');
  close(parseColor('hsl(120, 200%, 150%)'), { r: 255, g: 255, b: 255, a: 1 }, 'hsl s/l clamp');
});

test('whitespace tolerance', () => {
  close(parseColor('  #ff0000  '), { r: 255, g: 0, b: 0, a: 1 }, 'padded hex');
  close(parseColor('RGB( 0 , 255 , 0 )'), { r: 0, g: 255, b: 0, a: 1 }, 'messy rgb() spacing/case');
});

test('errors name the bad token', () => {
  assert.throws(() => parseColor('rgb(a, b, c)'), (e) => {
    assert.ok(e instanceof ColorError, 'should be a ColorError');
    assert.match(e.message, /"a"/, 'message names the bad token');
    return true;
  });
  assert.throws(() => parseColor('#12345'), ColorError, 'bad hex length');
  assert.throws(() => parseColor('notacolor'), ColorError, 'unknown keyword');
  assert.throws(() => parseColor('hsl(x, 50%, 50%)'), (e) => {
    assert.match(e.message, /"x"/, 'hsl error names bad hue token');
    return true;
  });
  assert.throws(() => parseColor('rgb(255, 0)'), ColorError, 'wrong arity');
});

